INSERT INTO `eb_user_feedback` VALUES (9, 9, 'question', '电费余额在哪里查看？', 'processed', '2025-03-15 10:00:00', '2025-03-15 11:00:00', 1, '在个人中心查看', '2025-03-15 10:00:00', '2025-04-15 09:59:53');
INSERT INTO `eb_user_feedback` VALUES (10, 1, 'complaint', '支付失败未退款', '正在处理', '2025-03-15 14:00:00', NULL, 4, '处理', '2025-03-15 14:00:00', '2025-04-15 09:59:53');
INSERT INTO `eb_user_feedback` VALUES (11, 1, 'complaint', '电费计算不准确，本月电费明显高于往常', 'processed', '2023-09-05 10:00:00', '2023-09-06 14:00:00', 3, '尊敬的用户，我们已核实您的用电情况，确实存在计算误差，已为您重新计算并更正账单。', '2023-09-05 10:00:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (12, 3, 'suggestion', '建议增加更多的在线支付方式，如银联支付等', 'closed', '2023-09-10 11:30:00', '2023-09-12 09:15:00', 3, '感谢您的建议，我们正在与更多支付渠道合作，预计下个月会上线银联支付功能。', '2023-09-10 11:30:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (13, 5, 'question', '工业用户的峰谷电价是如何划分的？', 'processed', '2023-09-15 14:20:00', '2023-09-16 10:30:00', 3, '工业用户峰时段为8:00-12:00和17:00-21:00，谷时段为22:00-次日6:00，其余为平时段。详情可查看官网电价说明。', '2023-09-15 14:20:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (14, 2, 'complaint', '电表显示不清晰，希望能派人检查', 'pending', '2023-09-20 09:45:00', NULL, 0, NULL, '2023-09-20 09:45:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (15, 7, 'complaint', '上月停电没有提前通知，导致学校工作受到影响', 'processing', '2023-09-25 16:10:00', NULL, 3, NULL, '2023-09-25 16:10:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (16, 8, 'suggestion', '希望能提供电费分析报告，帮助用户了解用电习惯', 'closed', '2023-10-01 10:20:00', '2023-10-02 11:00:00', 3, '非常感谢您的建议，我们已将此功能加入产品规划，预计明年第一季度上线。', '2023-10-01 10:20:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (17, 4, 'question', '如何申请电费补贴？', 'processed', '2023-10-05 14:30:00', '2023-10-06 09:45:00', 3, '您可以携带身份证、户口本等资料到就近的营业厅申请，或登录官网\"补贴申请\"栏目在线提交申请。', '2023-10-05 14:30:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (18, 9, 'complaint', '医院急诊部的备用电源切换有延迟，存在安全隐患', 'processing', '2023-10-10 11:15:00', NULL, 3, NULL, '2023-10-10 11:15:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (19, 6, 'suggestion', '建议增加微信公众号缴费提醒功能', 'pending', '2023-10-15 15:40:00', NULL, 0, NULL, '2023-10-15 15:40:00', '2025-04-20 00:01:09');
INSERT INTO `eb_user_feedback` VALUES (20, 10, 'question', '家用电器能效标识如何查询？', 'processed', '2023-10-20 10:10:00', '2023-10-21 14:00:00', 3, '您可以通过国家能效标识查询平台（网址：https://www.energylabel.gov.cn/）输入电器型号进行查询。', '2023-10-20 10:10:00', '2025-04-20 00:01:09');
