  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `last_meter_reading_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '周期最后一次抄表时间',
  `start_meter_reading_date` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '周期内开始读表的时间',
