  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `start_reading` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '一个周期内读表开始的度数',
  `ending_reading` decimal(9, 2) NULL DEFAULT 0.00 COMMENT '一个周期内读表现在的度数',
  `valid_type` int(11) NULL DEFAULT NULL COMMENT '有效状态',
