  `refund_status` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'none' COMMENT '退款状态: none（无）/processing（处理中）/success（成功）/failed（失败）',
  `refund_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '退款金额',
