CREATE TABLE `eb_rate`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '费率ID',
  `user_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户类型',
  `peak_price` decimal(10, 4) NULL DEFAULT NULL COMMENT '峰时电价(元/度)',
  `flat_price` decimal(10, 4) NULL DEFAULT NULL COMMENT '平时电价(元/度)',
  `valley_price` decimal(10, 4) NULL DEFAULT NULL COMMENT '谷时电价(元/度)',
