  `peak_end` time NULL DEFAULT NULL COMMENT '峰时段结束时间',
  `valley_start` time NULL DEFAULT NULL COMMENT '谷时段开始时间',
  `valley_end` time NULL DEFAULT NULL COMMENT '谷时段结束时间',
  `summer_period` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '夏季时段(如\"06-01至08-31\")',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '状态: 0禁用/1启用',
  `effective_date` date NOT NULL COMMENT '生效日期',
