  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `request_body` varchar(4000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '请求体',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_operator_id`(`operator_id`) USING BTREE,
  INDEX `idx_operation_type`(`operation_type`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 510 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_system_log
-- ----------------------------

-- ----------------------------
-- Table structure for eb_usage_summary
-- ----------------------------
DROP TABLE IF EXISTS `eb_usage_summary`;
CREATE TABLE `eb_usage_summary`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '汇总ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `meter_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '电表编号',
  `summary_date_start` date NOT NULL COMMENT '汇总日期始',
  `peak_usage` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '峰时段用电量(度)',
  `flat_usage` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平时段用电量(度)',
  `valley_usage` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '谷时段用电量(度)',
  `total_usage` decimal(10, 2) NULL DEFAULT NULL COMMENT '总用电量(度)',
  `peak_cost` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '峰时段电费(元)',
  `flat_cost` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '平时段电费(元)',
  `valley_cost` decimal(10, 2) NOT NULL DEFAULT 0.00 COMMENT '谷时段电费(元)',
  `total_cost` decimal(10, 2) NULL DEFAULT NULL COMMENT '总电费(元)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `summary_date_end` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '汇总的日期末',
  `date_type` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '用来表示当前是日的数据或者是月或者是年的数据',
  `bill_id` bigint(20) NULL DEFAULT NULL COMMENT '账单Id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_user_meter_date`(`user_id`, `meter_id`, `summary_date_start`) USING BTREE,
  UNIQUE INDEX `idx_bill_id`(`bill_id`) USING BTREE,
  INDEX `idx_date`(`summary_date_start`) USING BTREE,
  INDEX `idx_user`(`user_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '每日用电量及电费汇总表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_usage_summary
-- ----------------------------

-- ----------------------------
-- Table structure for eb_user
-- ----------------------------
DROP TABLE IF EXISTS `eb_user`;
CREATE TABLE `eb_user`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `account` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '账号',
  `password` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '密码',
  `username` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户名',
  `phone` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '电话',
  `address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '地址',
  `meter_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '电表编号',
  `user_type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '用户类型: 居民用户/商业用户',
  `account_status` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '正常' COMMENT '账号状态: 正常/欠费/停用',
  `id_card_no` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '身份证号',
  `last_payment_date` datetime NULL DEFAULT NULL COMMENT '最近缴费时间',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `valid_type` tinyint(4) NOT NULL DEFAULT 1 COMMENT '有效',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `account`(`account`) USING BTREE,
  UNIQUE INDEX `meter_no`(`meter_id`) USING BTREE,
  INDEX `idx_phone`(`phone`) USING BTREE,
  INDEX `idx_meter_no`(`meter_id`) USING BTREE,
  INDEX `idx_user_type`(`user_type`) USING BTREE,
  INDEX `idx_account_status`(`account_status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 58 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_user
-- ----------------------------

-- ----------------------------
-- Table structure for eb_user_feedback
-- ----------------------------
DROP TABLE IF EXISTS `eb_user_feedback`;
CREATE TABLE `eb_user_feedback`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '反馈ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `feedback_type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '反馈类型: complaint（投诉）/suggestion（建议）/question（问题）',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '反馈内容',
  `feedback_status` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'pending' COMMENT '状态: pending（待处理）/processed（已处理）/closed（已关闭）',
  `submit_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '提交时间',
  `process_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `processor_id` bigint(20) NOT NULL DEFAULT 0 COMMENT '处理人ID',
  `response` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '回复内容',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_status`(`feedback_status`) USING BTREE,
  INDEX `idx_submit_time`(`submit_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 24 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of eb_user_feedback
-- ----------------------------

-- ----------------------------
-- Table structure for eb_user_type
-- ----------------------------
DROP TABLE IF EXISTS `eb_user_type`;
CREATE TABLE `eb_user_type`  (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '用户类型ID，主键',
  `type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户类型名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '类型描述',
  `status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '状态：0-禁用，1-启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of eb_user_type
-- ----------------------------

